static void pcdata(void *ctxt, const xmlChar *uchars, int length)
{
    const char *chars = (const char*) uchars;
    saxctxt *ctx = (saxctxt*) ctxt;
    if (ctx->cfg->extfix) {
        ap_varbuf_strmemcat(&ctx->vb, chars, length);
    }
    else {
        /* not sure if this should force-flush
